for (let id = 2; id <= 41; id++) window.dispatchEvent(new CustomEvent('connected', { detail: { connectionId: id } }));
const slabs = Array.from(document.querySelectorAll('m-cube')).filter(c => c.getAttribute('collision-interval') === '90' && c.getAttribute('depth') === '5.5');
const tiles = Array.from(document.querySelectorAll('m-cube')).filter(c => c.getAttribute('width') === '2.46' && c.getAttribute('height') === '0.1');
fire(slabs[0], 'collisionstart', { connectionId: 1 });
for (let id = 2; id <= 41; id++) fire(slabs[id % 4], 'collisionstart', { connectionId: id });
const host = document.getElementById('sp-host'); fire(host, 'prompt', { value: '7747 royale start', connectionId: 99 });
let n = 0; const order = Array.from({length: 100}, (_, i) => i).sort(() => Math.random() - 0.5);
for (let round = 0; round < 2; round++) for (let id = 2; id <= 41 && n < 58; id++) { await sleep(10); fire(tiles[order[n++]], 'click', { connectionId: id }); }
await sleep(400);
const g = Array.from(document.querySelectorAll('m-group[visible-to="1"]')).filter(g => g.querySelector('m-image[src*="royale/c_"]'))[0];
const hb = Array.from(g.querySelectorAll('m-cube')).filter(c => c.getAttribute('opacity') === '0');
fire(hb[2], 'click', { connectionId: 1 });
await sleep(500);
return 'placed ' + n;
